    VARIANT_BUTTONS_KEY,
    VARIANT_BUTTONS_SOURCE_KEY,
    VARIANT_CONDITION_KEY,
    VARIANT_METADATA_KEY,
    VARIANT_TEXT_KEY,
    RegisteredResponse,
