# Stable finding codes surfaced to builders (log routing and test assertions).
EMPTY_RESPONSE_BODY_CODE = "mantle.validation.response.empty_body"
INVALID_CONDITION_CODE = "mantle.validation.response.invalid_condition"
INVALID_VARIANT_KEY_CODE = "mantle.validation.response.invalid_variant_key"
INVALID_VARIANT_SHAPE_CODE = "mantle.validation.response.invalid_variant_shape"
UNKNOWN_MEMORY_KEY_CODE = "mantle.validation.response.unknown_memory_key"
DEFAULT_REQUIRED_CODE = "mantle.validation.response.default_required"
MULTIPLE_DEFAULTS_CODE = "mantle.validation.response.multiple_defaults"
INVALID_BUTTON_PAYLOAD_CODE = "mantle.validation.response.invalid_button_payload"
INVALID_SET_MEMORY_VALUE_CODE = "mantle.validation.response.invalid_set_memory_value"
NOT_WRITABLE_MEMORY_KEY_CODE = "mantle.validation.response.not_writable_memory_key"


class ParsedResponseFile(NamedTuple):
    """One project-authored ``responses.yml`` and its lenient parse result."""

    path: Path
    registry: ResponseRegistry
    skill_id: str | None


def validate_project_response_variants(
    project_root: Path,
    *,
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> list[ValidationFinding]:
    """Load and validate every project ``responses.yml`` (parse + variant rules).

    Convenience wrapper around :func:`load_project_responses_for_validation`
    and :func:`validate_parsed_response_files` for tests and standalone use.
    """
    _merged, parse_findings, parsed_files = load_project_responses_for_validation(
        project_root
    )
    return parse_findings + validate_parsed_response_files(
        parsed_files,
        catalog=catalog,
        project_memory=project_memory,
    )


def load_project_responses_for_validation(
    project_root: Path,
) -> tuple[ResponseRegistry, list[ValidationFinding], list[ParsedResponseFile]]:
    """Load bundled defaults plus every project ``responses.yml`` leniently.

    Returns:
    - Merged registry (bundled defaults + valid project variants only).
    - Parse findings from each project file (unknown keys, bad shapes, …).
    - Per-file registries for follow-up variant-rule checks.
    """
    merged = load_bundled_response_registry()
    parse_findings: list[ValidationFinding] = []
    parsed_files: list[ParsedResponseFile] = []

    for path, skill_id in _iter_authored_response_files(project_root):
        file_registry, file_findings = parse_responses_file_leniently(path)
        parse_findings.extend(file_findings)
        parsed_files.append(ParsedResponseFile(path, file_registry, skill_id))
        merged = file_registry.merge(merged)

    return merged, parse_findings, parsed_files


def parse_responses_file_leniently(
    path: Path,
) -> tuple[ResponseRegistry, list[ValidationFinding]]:
    """Parse one ``responses.yml`` file without aborting on the first bad row.

    Invalid rows become findings; valid rows are kept so later checks can run
    on the same file.
    """
    if not path.is_file():
        return ResponseRegistry(), []

    with path.open(encoding="utf-8") as file_handle:
        raw_document = yaml.safe_load(file_handle) or {}

    entries = raw_document.get(RESPONSES_YAML_KEY)
    if not isinstance(entries, dict):
        return ResponseRegistry(), []

    findings: list[ValidationFinding] = []
    responses: dict[str, RegisteredResponse] = {}
    for response_name, variant_list in entries.items():
        registered, response_findings = _parse_variant_list_leniently(
            variant_list,
            source_path=path,
            response_name=str(response_name),
        )
        findings.extend(response_findings)
        if registered is not None:
            responses[str(response_name)] = registered

    return ResponseRegistry(responses=responses), findings


def validate_parsed_response_files(
    parsed_files: Iterable[ParsedResponseFile],
    *,
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> list[ValidationFinding]:
    """Run variant-rule checks on already-parsed project ``responses.yml`` files."""
    findings: list[ValidationFinding] = []
    for parsed_file in parsed_files:
        findings.extend(
            validate_response_variants(
                parsed_file.registry,
                catalog=catalog,
                project_memory=project_memory,
                source_path=parsed_file.path,
                observing_skill_id=parsed_file.skill_id,
            )
        )
    return findings


def validate_response_variants(
    registry: ResponseRegistry,
    *,
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    source_path: Path | None = None,
    observing_skill_id: str | None = None,
) -> list[ValidationFinding]:
    """Validate CRV shape rules for one registry snapshot (one file or merged).

    Checks empty ``text``, condition syntax, readable memory references, and
    default-variant rules. Does not re-parse YAML; use
    :func:`parse_responses_file_leniently` first when parse findings are needed.
    """
    skill_id = _resolve_observing_skill_id(source_path, observing_skill_id)
    readable_memory_keys = _memory_keys_readable_for_responses(
        catalog, project_memory, skill_id
    )
    skills_by_response = skills_referencing_responses(catalog)

    findings: list[ValidationFinding] = []
    for response_name, registered in registry.responses.items():
        settable_memory_keys = _button_writable_keys_for_response(
            catalog,
            project_memory,
            skill_id,
            response_name=response_name,
            skills_by_response=skills_by_response,
        )
        findings.extend(
            _validate_named_response(
                registered.variants,
                response_name=response_name,
                source_path=source_path,
                observing_skill_id=skill_id,
                readable_memory_keys=readable_memory_keys,
                settable_memory_keys=settable_memory_keys,
                catalog=catalog,
                project_memory=project_memory,
                skills_by_response=skills_by_response,
            )
        )
    return findings


def iter_project_response_registries(
    project_root: Path,
) -> Iterable[tuple[Path, ResponseRegistry, str | None]]:
    """Yield each project ``responses.yml`` path, registry, and owning skill id.

    Uses lenient parsing (invalid rows omitted). Call
    :func:`parse_responses_file_leniently` directly when parse findings are
    required.
    """
    for path, skill_id in _iter_authored_response_files(project_root):
        registry, _ = parse_responses_file_leniently(path)
        yield path, registry, skill_id


# ---------------------------------------------------------------------------
# Project file discovery
# ---------------------------------------------------------------------------


def _iter_authored_response_files(
    project_root: Path,
) -> Iterator[tuple[Path, str | None]]:
    """Yield ``(responses.yml path, owning skill id)`` for project-authored files.

    Skill files are yielded in sorted directory order; the project-root file
    (skill id ``None``) is yielded last.
    """
    project_root = Path(project_root)
    skills_root = project_root / MANTLE_SKILLS_DIR
    if skills_root.is_dir():
        for skill_dir in sorted(skills_root.iterdir()):
            if not skill_dir.is_dir() or skill_dir.name.startswith("_"):
                continue
            responses_path = skill_dir / RESPONSES_FILENAME
            if responses_path.is_file():
                yield responses_path, skill_dir.name

    top_level = project_root / RESPONSES_FILENAME
    if top_level.is_file():
        yield top_level, None


# ---------------------------------------------------------------------------
# Lenient YAML parsing
# ---------------------------------------------------------------------------


def _parse_variant_list_leniently(
    variant_list: object,
    *,
    source_path: Path,
    response_name: str,
) -> tuple[RegisteredResponse | None, list[ValidationFinding]]:
    """Parse one response's variant list, collecting a finding per bad row.

    Empty lists and non-list values (scalar, mapping, ``null``) produce an
    :data:`INVALID_VARIANT_SHAPE_CODE` finding at the response level so train
    catches shapes that would otherwise vanish from the registry and fail
    closed at delivery.
    """
    if not isinstance(variant_list, list) or not variant_list:
        location = _response_location(source_path, response_name)
        return None, [
            _invalid_variant_shape_finding(
                location,
                "must be a non-empty list of variants (each a mapping with a "
                "text field or a scalar text value).",
            )
        ]

    parsed_variants: list[ResponseDefinition] = []
    findings: list[ValidationFinding] = []
    for index, raw_variant in enumerate(variant_list):
        definition, row_findings = _parse_variant_row_leniently(
            raw_variant,
            source_path=source_path,
            response_name=response_name,
            variant_index=index,
        )
        findings.extend(row_findings)
        if definition is not None:
            parsed_variants.append(definition)

    if not parsed_variants:
        return None, findings
    return RegisteredResponse(variants=tuple(parsed_variants)), findings


def _parse_variant_row_leniently(
    raw_variant: object,
    *,
    source_path: Path,
    response_name: str,
    variant_index: int,
) -> tuple[ResponseDefinition | None, list[ValidationFinding]]:
    """Parse one YAML variant row into a :class:`ResponseDefinition` or a finding."""
    location = _variant_location(source_path, response_name, variant_index)

    if isinstance(raw_variant, dict):
        return _parse_variant_mapping_leniently(raw_variant, location=location)
    if isinstance(raw_variant, (str, int, float, bool)):
        return ResponseDefinition(text=str(raw_variant)), []

    return None, [
        _invalid_variant_shape_finding(
            location,
            "must be a mapping with a text field or a scalar text value.",
        )
    ]


def _parse_variant_mapping_leniently(
    mapping: dict[object, object],
    *,
    location: str,
) -> tuple[ResponseDefinition, list[ValidationFinding]]:
    """Parse a variant mapping, reporting unknown keys but keeping allowed fields."""
    findings: list[ValidationFinding] = []
    unknown_keys = sorted(str(key) for key in set(mapping) - ALLOWED_VARIANT_KEYS)
    if unknown_keys:
        findings.append(_unknown_variant_key_finding(location, unknown_keys))

    text = _coerce_variant_text(mapping.get(VARIANT_TEXT_KEY, ""))
    metadata_raw = mapping.get(VARIANT_METADATA_KEY)
    metadata = _coerce_variant_metadata(metadata_raw)
    rephrase = _coerce_rephrase_flag(metadata_raw)
    condition, condition_findings = _coerce_variant_condition(
        mapping.get(VARIANT_CONDITION_KEY),
        location=location,
    )
    findings.extend(condition_findings)
    buttons, button_source, button_findings = _coerce_variant_buttons(
        mapping.get(VARIANT_BUTTONS_KEY),
        location=location,
    )
    findings.extend(button_findings)

    return (
        ResponseDefinition(
            text=text,
            rephrase=rephrase,
            condition=condition,
            buttons=buttons,
            button_source=button_source,
            metadata=metadata,
        ),
        findings,
    )


def _coerce_variant_text(text_raw: object) -> str:
    """Return variant ``text`` as a string (empty when absent or ``None``)."""
    if text_raw is None:
        return ""
    return str(text_raw)


def _coerce_rephrase_flag(metadata_raw: object) -> bool:
    """Return ``metadata.rephrase`` when present; otherwise ``False``."""
    if not isinstance(metadata_raw, dict):
        return False
    return bool(metadata_raw.get(METADATA_REPHRASE_KEY))


def _coerce_variant_metadata(metadata_raw: object) -> dict[str, object]:
    """Return variant ``metadata`` as a dict, or ``{}`` when absent or invalid."""
    if not isinstance(metadata_raw, dict):
        return {}
    return dict(metadata_raw)


def _coerce_variant_condition(
    condition_raw: object,
    *,
    location: str,
) -> tuple[str | None, list[ValidationFinding]]:
    """Return ``(condition, findings)`` for a raw YAML ``condition`` value."""
    if condition_raw is None:
        return None, []
    if isinstance(condition_raw, str):
        return condition_raw, []
    return None, [
        _invalid_variant_shape_finding(
            location,
            f"has response variant {VARIANT_CONDITION_KEY!r} that must be a string.",
        )
    ]


def _coerce_variant_buttons(
    buttons_raw: object,
    *,
    location: str,
) -> tuple[tuple[ResponseButton, ...], str | None, list[ValidationFinding]]:
    """Parse static buttons or a button source, collecting findings."""
    if buttons_raw is None:
        return (), None, []
    if isinstance(buttons_raw, dict):
        return _coerce_button_source(buttons_raw, location=location)
    if not isinstance(buttons_raw, list):
        return (
            (),
            None,
            [
                _invalid_variant_shape_finding(
                    location,
                    f"has response variant {VARIANT_BUTTONS_KEY!r} that must be a "
                    "list of mappings or a mapping with a source tool.",
                )
            ],
        )

    findings: list[ValidationFinding] = []
    buttons: list[ResponseButton] = []
    for button_index, item in enumerate(buttons_raw):
        button, button_findings = _parse_button_mapping_leniently(
            item,
            location=f"{location}, button {button_index}",
        )
        findings.extend(button_findings)
        if button is not None:
            buttons.append(button)
    return tuple(buttons), None, findings


def _coerce_button_source(
    source_mapping: dict[object, object],
    *,
    location: str,
) -> tuple[tuple[ResponseButton, ...], str | None, list[ValidationFinding]]:
    """Parse a button source mapping, reporting unknown keys and invalid values."""
    findings: list[ValidationFinding] = []
    unknown_keys = sorted(
        str(key) for key in set(source_mapping) - ALLOWED_BUTTON_SOURCE_KEYS
    )
    if unknown_keys:
        keys_text = ", ".join(repr(key) for key in unknown_keys)
        findings.append(
            ValidationFinding(
                code=INVALID_VARIANT_KEY_CODE,
                message=(
                    f"{location} has unknown response button source key(s): "
                    f"{keys_text}. Allowed keys: {VARIANT_BUTTONS_SOURCE_KEY}."
                ),
            )
        )

    source = source_mapping.get(VARIANT_BUTTONS_SOURCE_KEY)
    if not isinstance(source, str) or not source.strip():
        findings.append(
            _invalid_variant_shape_finding(
                location,
                "has a response button source that must be a non-empty string.",
            )
        )
        return (), None, findings
    return (), source.strip(), findings


def _parse_button_mapping_leniently(
    item: object,
    *,
    location: str,
) -> tuple[ResponseButton | None, list[ValidationFinding]]:
    """Parse one button mapping via the public button parse API.

    Unknown keys become findings while allowed fields are still parsed into a
    model. Shape errors become findings and omit the button.
    """
    if not isinstance(item, dict):
        return None, [
            _invalid_variant_shape_finding(
                location,
                "each response button must be a mapping with a title field.",
            )
        ]

    button_result = ResponseRegistry.try_parse_button(item)
    findings: list[ValidationFinding] = []
    if button_result.unknown_keys:
        findings.append(
            _unknown_button_key_finding(location, list(button_result.unknown_keys))
        )
    if button_result.error is not None:
        findings.append(
            ValidationFinding(
                code="responses.registry.invalid_variant",
                message=f"{location}: {button_result.error}",
            )
        )
        return None, findings
    return button_result.button, findings


def _unknown_button_key_finding(
    location: str, unknown_keys: list[str]
) -> ValidationFinding:
    """Build a finding for disallowed keys on a button mapping."""
    keys_text = ", ".join(repr(key) for key in unknown_keys)
    allowed_text = ", ".join(sorted(ALLOWED_BUTTON_KEYS))
    return ValidationFinding(
        code=INVALID_VARIANT_KEY_CODE,
        message=(
            f"{location} has unknown response button key(s): {keys_text}. "
            f"Allowed keys: {allowed_text}."
        ),
    )


def _unknown_variant_key_finding(
    location: str, unknown_keys: list[str]
) -> ValidationFinding:
    """Build a finding for disallowed top-level variant keys."""
    keys_text = ", ".join(repr(key) for key in unknown_keys)
    allowed_text = ", ".join(sorted(ALLOWED_VARIANT_KEYS))
    return ValidationFinding(
        code=INVALID_VARIANT_KEY_CODE,
        message=(
            f"{location} has unknown response variant key(s): {keys_text}. "
            f"Allowed keys: {allowed_text}."
        ),
    )


def _invalid_variant_shape_finding(location: str, detail: str) -> ValidationFinding:
    """Build a finding for a variant row that cannot be parsed."""
    return ValidationFinding(
        code=INVALID_VARIANT_SHAPE_CODE,
        message=f"{location} {detail}",
    )


# ---------------------------------------------------------------------------
# Variant rule validation
# ---------------------------------------------------------------------------


def _validate_named_response(
    variants: tuple[ResponseDefinition, ...],
    *,
    response_name: str,
    source_path: Path | None,
    observing_skill_id: str | None,
    readable_memory_keys: frozenset[str],
    settable_memory_keys: frozenset[str],
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    skills_by_response: Mapping[str, frozenset[str]],
) -> list[ValidationFinding]:
    """Validate default-variant rules and each row for one response name."""
    findings = _validate_default_variant_rules(
        variants,
        response_name=response_name,
        source_path=source_path,
    )
    for index, variant in enumerate(variants):
        findings.extend(
            _validate_variant_row(
                variant,
                response_name=response_name,
                variant_index=index,
                source_path=source_path,
                observing_skill_id=observing_skill_id,
                readable_memory_keys=readable_memory_keys,
                settable_memory_keys=settable_memory_keys,
                catalog=catalog,
                project_memory=project_memory,
                skills_by_response=skills_by_response,
            )
        )
    return findings


def _validate_default_variant_rules(
    variants: tuple[ResponseDefinition, ...],
    *,
    response_name: str,
    source_path: Path | None,
) -> list[ValidationFinding]:
    """Require exactly one default row when any variant has a ``condition``."""
    default_indices = [
        index for index, variant in enumerate(variants) if variant.condition is None
    ]
    has_conditioned_row = any(variant.condition is not None for variant in variants)
    if not has_conditioned_row:
        return []

    location = _response_location(source_path, response_name)
    if not default_indices:
        return [
            ValidationFinding(
                code=DEFAULT_REQUIRED_CODE,
                message=(
                    f"{location} defines conditioned variants but no default variant "
                    "(omit ``condition`` on exactly one variant)."
                ),
            )
        ]
    if len(default_indices) > 1:
        indices = ", ".join(str(index) for index in default_indices)
        return [
            ValidationFinding(
                code=MULTIPLE_DEFAULTS_CODE,
                message=(
                    f"{location} has multiple default variants at index(es) {indices}; "
                    "exactly one variant must omit ``condition``."
                ),
            )
        ]
    return []


def _validate_variant_row(
    variant: ResponseDefinition,
    *,
    response_name: str,
    variant_index: int,
    source_path: Path | None,
    observing_skill_id: str | None,
    readable_memory_keys: frozenset[str],
    settable_memory_keys: frozenset[str],
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    skills_by_response: Mapping[str, frozenset[str]],
) -> list[ValidationFinding]:
    """Validate one variant's ``text``, ``condition``, and ``buttons``."""
    location = _variant_location(source_path, response_name, variant_index)
    findings: list[ValidationFinding] = []

    if not variant.text.strip():
        findings.append(
            ValidationFinding(
                code=EMPTY_RESPONSE_BODY_CODE,
                message=(
                    f"{location} has an empty ``text`` body; provide "
                    "non-whitespace text."
                ),
            )
        )

    if variant.condition is not None:
        findings.extend(
            _validate_condition_expression(
                variant.condition,
                location=location,
                readable_memory_keys=readable_memory_keys,
                observing_skill_id=observing_skill_id,
            )
        )

    for button_index, button in enumerate(variant.buttons):
        findings.extend(
            _button_findings(
                button,
                location=_button_location(
                    source_path, response_name, variant_index, button_index
                ),
                observing_skill_id=observing_skill_id,
                readable_memory_keys=readable_memory_keys,
                settable_memory_keys=settable_memory_keys,
                catalog=catalog,
                project_memory=project_memory,
                response_name=response_name,
                skills_by_response=skills_by_response,
            )
        )
    return findings


def _button_findings(
    button: ResponseButton,
    *,
    location: str,
    observing_skill_id: str | None,
    readable_memory_keys: frozenset[str],
    settable_memory_keys: frozenset[str],
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    response_name: str,
    skills_by_response: Mapping[str, frozenset[str]],
) -> list[ValidationFinding]:
    if button.payload is None:
        return []
    if not is_set_memory_payload(button.payload):
        return []
    return _set_memory_payload_findings(
        button.payload,
        location=location,
        observing_skill_id=observing_skill_id,
        readable_memory_keys=readable_memory_keys,
        settable_memory_keys=settable_memory_keys,
        catalog=catalog,
        project_memory=project_memory,
        response_name=response_name,
        skills_by_response=skills_by_response,
    )


def _set_memory_payload_findings(
    payload: str,
    *,
    location: str,
    observing_skill_id: str | None,
    readable_memory_keys: frozenset[str],
    settable_memory_keys: frozenset[str],
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    response_name: str,
    skills_by_response: Mapping[str, frozenset[str]],
) -> list[ValidationFinding]:
    try:
        parsed = parse_static_set_memory_payload(payload)
    except SetMemoryPayloadError as exc:
        return [
            ValidationFinding(
                code=INVALID_BUTTON_PAYLOAD_CODE,
                message=f"{location} has an invalid set-memory ``payload``: {exc}",
            )
        ]

    findings = _memory_reference_findings(
        (parsed.memory_key,),
        location=location,
        readable_memory_keys=readable_memory_keys,
        observing_skill_id=observing_skill_id,
    )
    if findings:
        return findings

    if parsed.memory_key not in settable_memory_keys:
        denying = _skills_denying_button_write(
            catalog,
            project_memory,
            memory_key=parsed.memory_key,
            response_name=response_name,
            skills_by_response=skills_by_response,
            observing_skill_id=observing_skill_id,
        )
        findings.append(
            ValidationFinding(
                code=NOT_WRITABLE_MEMORY_KEY_CODE,
                message=_not_writable_memory_key_message(
                    location=location,
                    memory_key=parsed.memory_key,
                    observing_skill_id=observing_skill_id,
                    denying_skill_ids=denying,
                ),
            )
        )
        return findings

    field = _memory_field_for_key(
        parsed.memory_key, catalog=catalog, project_memory=project_memory
    )
    if field is None:
        return findings

    if coerce_set_memory_button_value(parsed.value, field) is not None:
        return findings

    findings.append(
        ValidationFinding(
            code=INVALID_SET_MEMORY_VALUE_CODE,
            message=_invalid_set_memory_value_message(
                location=location,
                memory_key=parsed.memory_key,
                value=parsed.value,
                field=field,
            ),
        )
    )
    return findings


def _invalid_set_memory_value_message(
    *,
    location: str,
    memory_key: str,
    value: str,
    field: MemoryField,
) -> str:
    """Explain why a ``set:`` button value is invalid for *field*."""
    if field.type == MEMORY_FIELD_TYPE_CATEGORICAL and field.enum_values:
        allowed_text = ", ".join(sorted(str(v) for v in field.enum_values))
        return (
            f"{location} sets {memory_key!r} to {value!r}, "
            f"which is not one of the declared categorical values: "
            f"{allowed_text}."
        )
    if field.type == MEMORY_FIELD_TYPE_LIST:
        return (
            f"{location} sets {memory_key!r} to {value!r}, "
            "which is not a JSON array (required for ``list`` memory fields)."
        )
    if field.type == MEMORY_FIELD_TYPE_JSON:
        return (
            f"{location} sets {memory_key!r} to {value!r}, "
            "which is not valid JSON (required for ``json`` memory fields)."
        )
    if field.type in {
        MEMORY_FIELD_TYPE_BOOL,
        MEMORY_FIELD_TYPE_INT,
        MEMORY_FIELD_TYPE_FLOAT,
    }:
        return (
            f"{location} sets {memory_key!r} to {value!r}, "
            f"which cannot be coerced to memory type {field.type!r}."
        )
    return (
        f"{location} sets {memory_key!r} to {value!r}, "
        f"which is not valid for memory type {field.type!r}."
    )


def _memory_field_for_key(
    memory_key: str,
    *,
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
) -> MemoryField | None:
    if memory_key.startswith(f"{PROJECT_NAMESPACE}."):
        entry_name = memory_key[len(PROJECT_NAMESPACE) + 1 :]
        return project_memory.fields.get(entry_name)
    skill_id, separator, entry_name = memory_key.partition(".")
    if not separator:
        return None
    skill = catalog.skills.get(skill_id)
    if skill is None:
        return None
    return skill.memory.definition.all_fields().get(entry_name)


def _validate_condition_expression(
    condition: str,
    *,
    location: str,
    readable_memory_keys: frozenset[str],
    observing_skill_id: str | None,
) -> list[ValidationFinding]:
    """Validate syntax and memory references in one ``condition`` expression."""
    stripped = condition.strip()
    if is_empty_prose_if_condition(stripped):
        return [
            ValidationFinding(
                code=INVALID_CONDITION_CODE,
                message=(
                    f"{location} has an empty ``condition``; provide an "
                    "expression such as "
                    "'session.<skill_id>.<entry> == …'."
                ),
            )
        ]

    syntax_error = _condition_syntax_error(stripped)
    if syntax_error is not None:
        return [
            ValidationFinding(
                code=INVALID_CONDITION_CODE,
                message=f"{location} has an invalid ``condition``: {syntax_error}",
            )
        ]

    memory_keys = _condition_memory_keys(stripped)
    if memory_keys is None:
        return [
            ValidationFinding(
                code=INVALID_CONDITION_CODE,
                message=(
                    f"{location} has an invalid ``condition``: "
                    "could not extract memory references."
                ),
            )
        ]

    return _memory_reference_findings(
        memory_keys,
        location=location,
        readable_memory_keys=readable_memory_keys,
        observing_skill_id=observing_skill_id,
    )


def _condition_syntax_error(condition: str) -> str | None:
    """Return an error message when *condition* syntax is invalid, else ``None``."""
    try:
        validate_condition_syntax(condition)
    except ConditionEvaluationError as exc:
        return str(exc)
    return None


def _condition_memory_keys(condition: str) -> frozenset[str] | None:
    """Return memory keys referenced in *condition*, or ``None`` when parsing fails."""
    try:
        return extract_memory_keys(condition)
    except ConditionEvaluationError:
        return None


def _memory_reference_findings(
    memory_keys: Iterable[str],
    *,
    location: str,
    readable_memory_keys: frozenset[str],
    observing_skill_id: str | None,
) -> list[ValidationFinding]:
    """Build findings for memory keys that are not readable at delivery time."""
    findings: list[ValidationFinding] = []
    for memory_key in sorted(memory_keys):
        if memory_key.startswith(f"{SYSTEM_NAMESPACE}."):
            findings.append(
                ValidationFinding(
                    code=UNKNOWN_MEMORY_KEY_CODE,
                    message=(
                        f"{location} references engine-internal system memory "
                        f"{memory_key!r}. Builder ``condition`` expressions must "
                        "use skill or project memory only."
                    ),
                )
            )
            continue
        if memory_key in readable_memory_keys:
            continue
        findings.append(
            ValidationFinding(
                code=UNKNOWN_MEMORY_KEY_CODE,
                message=_unknown_memory_key_message(
                    location=location,
                    memory_key=memory_key,
                    observing_skill_id=observing_skill_id,
                ),
            )
        )
    return findings


# ---------------------------------------------------------------------------
# Memory readability helpers
# ---------------------------------------------------------------------------


def _resolve_observing_skill_id(
    source_path: Path | None,
    observing_skill_id: str | None,
) -> str | None:
    """Return the skill whose readable memory set applies to this file."""
    if observing_skill_id is not None:
        return observing_skill_id
    return _skill_id_from_responses_path(source_path)


def _memory_keys_readable_for_responses(
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    observing_skill_id: str | None,
) -> frozenset[str]:
    """Return memory keys readable when this ``responses.yml`` may be delivered.

    Shared by ``condition`` expressions and ``set:`` button payloads. Per-skill
    files use that skill's readable set
    (:func:`~rasa.mantle.memory.manager.readable_memory_slot_names`).
    Project-root files use the intersection across all skills.
    """
    return _memory_keys_for_responses_file(
        catalog,
        observing_skill_id,
        per_skill=lambda skill_id: readable_memory_slot_names(
            catalog, project_memory, skill_id
        ),
        when_no_skills=lambda: frozenset(
            f"{PROJECT_NAMESPACE}.{field_name}" for field_name in project_memory.fields
        ),
    )


def _memory_keys_for_responses_file(
    catalog: SkillCatalog,
    observing_skill_id: str | None,
    *,
    per_skill: Callable[[str], frozenset[str]],
    when_no_skills: Callable[[], frozenset[str]],
) -> frozenset[str]:
    """Scope a per-skill memory key set to one ``responses.yml`` file.

    Project-root files use the intersection across all skills (any skill may
    deliver those responses for readability / placeholder resolution).
    """
    if observing_skill_id is not None:
        return per_skill(observing_skill_id)

    if not catalog.skills:
        return when_no_skills()

    skill_sets = [per_skill(skill_id) for skill_id in catalog.skills]
    intersection = skill_sets[0]
    for keys in skill_sets[1:]:
        intersection &= keys
    return frozenset(intersection)


def _button_writable_keys_for_response(
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    observing_skill_id: str | None,
    *,
    response_name: str,
    skills_by_response: Mapping[str, frozenset[str]],
) -> frozenset[str]:
    """Return keys a ``set:`` button on *response_name* may write.

    Skill-local ``responses.yml`` uses that skill's button-writable set.
    Project-root files intersect writable keys across skills that **reference**
    the response (flow ``utter_*`` / collect utterance / tool outcomes /
    verbatim triggers). Skills that never use the response are ignored. When
    no skill references it, only declared project fields are allowed.
    """
    if observing_skill_id is not None:
        return button_writable_memory_keys_for_skill(
            catalog, project_memory, observing_skill_id
        )

    referencing_skill_ids = skills_by_response.get(response_name, frozenset())
    if not referencing_skill_ids:
        return button_writable_memory_keys_for_skill(catalog, project_memory, None)

    skill_sets = [
        button_writable_memory_keys_for_skill(catalog, project_memory, skill_id)
        for skill_id in sorted(referencing_skill_ids)
    ]
    intersection = skill_sets[0]
    for keys in skill_sets[1:]:
        intersection &= keys
    return frozenset(intersection)


def _skills_denying_button_write(
    catalog: SkillCatalog,
    project_memory: ProjectMemorySchema,
    *,
    memory_key: str,
    response_name: str,
    skills_by_response: Mapping[str, frozenset[str]],
    observing_skill_id: str | None,
) -> frozenset[str]:
    """Return skill ids that use *response_name* but cannot write *memory_key*."""
    if observing_skill_id is not None:
        writable = button_writable_memory_keys_for_skill(
            catalog, project_memory, observing_skill_id
        )
        if memory_key in writable:
            return frozenset()
        return frozenset({observing_skill_id})

    referencing_skill_ids = skills_by_response.get(response_name, frozenset())
    denying: set[str] = set()
    for skill_id in referencing_skill_ids:
        writable = button_writable_memory_keys_for_skill(
            catalog, project_memory, skill_id
        )
        if memory_key not in writable:
            denying.add(skill_id)
    return frozenset(denying)


def _skill_id_from_responses_path(source_path: Path | None) -> str | None:
    """Infer skill id from ``skills/<id>/responses.yml`` when not passed explicitly."""
    if source_path is None or source_path.name != RESPONSES_FILENAME:
        return None
    skill_dir = source_path.parent
    if skill_dir.parent.name != MANTLE_SKILLS_DIR:
        return None
    return skill_dir.name


def _unknown_memory_key_message(
    *,
    location: str,
    memory_key: str,
    observing_skill_id: str | None,
) -> str:
    """Human-readable explanation for an unreadable memory reference."""
    if observing_skill_id is not None:
        return (
            f"{location} references memory key {memory_key!r} that is not readable "
            f"while skill {observing_skill_id!r} is active. Use this skill's own "
            "``memory.yml`` fields, another skill's public fields, or project "
            "``memory.yml`` entries (not another skill's private slots or "
            "``system.*``)."
        )
    return (
        f"{location} references memory key {memory_key!r} that is not readable "
        "from every skill while project-root ``responses.yml`` may be delivered "
        "by any skill. Use project ``memory.yml`` or each skill's public fields "
        "only (not private slots or ``system.*``)."
    )


def _not_writable_memory_key_message(
    *,
    location: str,
    memory_key: str,
    observing_skill_id: str | None,
    denying_skill_ids: frozenset[str] = frozenset(),
) -> str:
    """Human-readable explanation for a ``set:`` target outside the writable set."""
    if observing_skill_id is not None:
        return (
            f"{location} references memory key {memory_key!r} that is not "
            f"writable via a ``set:`` button while skill {observing_skill_id!r} "
            "is active. Use this skill's own declared fields or project "
            "``memory.yml`` entries "
            "(``llm_settable`` is not required — button taps are engine writes, "
            "not ``set_fields``)."
        )
    if denying_skill_ids:
        skill_list = ", ".join(repr(skill_id) for skill_id in sorted(denying_skill_ids))
        return (
            f"{location} references memory key {memory_key!r} that is not "
            f"writable via a ``set:`` button for skill(s) {skill_list}, which "
            "reference this response. Use a declared field those skills can "
            "write (their own memory or project ``memory.yml``), or stop those "
            "skills from using this response "
            "(``llm_settable`` is not required — button taps are engine writes)."
        )
    return (
        f"{location} references memory key {memory_key!r} that is not a "
        "declared project ``memory.yml`` field writable via a ``set:`` button "
        "(``llm_settable`` is not required — button taps are engine writes)."
    )


# ---------------------------------------------------------------------------
# Finding location strings
# ---------------------------------------------------------------------------


def _response_location(source_path: Path | None, response_name: str) -> str:
    """Prefix findings with file path and response name when known."""
    if source_path is None:
        return f"Response {response_name!r}"
    return f"{source_path}: response {response_name!r}"


def _variant_location(
    source_path: Path | None,
    response_name: str,
    variant_index: int,
) -> str:
    """Prefix findings with file path, response name, and variant index."""
    return f"{_response_location(source_path, response_name)}, variant {variant_index}"


def _button_location(
    source_path: Path | None,
    response_name: str,
    variant_index: int,
    button_index: int,
) -> str:
    """Prefix findings with file path, response name, variant, and button index."""
    return (
        f"{_variant_location(source_path, response_name, variant_index)}, "
        f"button {button_index}"
    )
